def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_build:
            core_part, pre_release = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            pre_release = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if pre_release:
            identifiers = pre_release.split('.')
            parsed_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    parsed_identifiers.append((0, int(ident)))
                else:
                    parsed_identifiers.append((1, ident))
        else:
            parsed_identifiers = None

        return (major, minor, patch, parsed_identifiers)

    def compare_key(version_str):
        major, minor, patch, pre_release = parse_version(version_str)

        # For sorting: version without pre-release sorts after version with pre-release
        # So we use (major, minor, patch, has_pre_release, pre_release_identifiers)
        # where has_pre_release is False (0) if pre_release exists, True (1) if it doesn't
        if pre_release is None:
            return (major, minor, patch, 1)
        else:
            return (major, minor, patch, 0, pre_release)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

